import Typography from "@mui/material/Typography";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import Box from "@mui/material/Box";
import IconButton from "@mui/material/IconButton";
import CustomDataGrid from "src/@core/components/data-grid";
import Chip from "@mui/material/Chip";
import { styled } from "@mui/material/styles";
import { Avatar, Button } from "@mui/material";
import { MEDIA_URL } from "src/network/endpoints";

const TableResourcesDetails = ({
  rows,
  totalCount,
  setCurrentPage,
  currentPage,
  setPageSize,
  pageSize,
  loading,
  toggleEdit,
  toggleDelete,
  onCellClick,
}) => {
  return (
    <>
      <CustomDataGrid
        loading={loading}
        rowCount={totalCount}
        rows={rows}
        handleCellClick={onCellClick}
        columns={[
          {
            field: "title",
            flex: 1,
            minWidth: 200,
            sortable: false,
            headerName: "Title",
            renderCell: ({ row }) => (
              <Typography noWrap variant="body2" title={row.title}>
                {row.title}
              </Typography>
            ),
          },

          {
            field: "resources_image",
            minWidth: 150,
            flex: 0.5,
            sortable: false,
            headerName: "Resources Image",
            renderCell: ({ row }) => (
              <Avatar src={`${MEDIA_URL}${row.resources_image}`} />
            ),
          },
          {
            field: "resources_link",
            flex: 1,
            minWidth: 200,
            sortable: false,
            headerName: "Resources Link",
            renderCell: ({ row }) => (
              <Typography noWrap variant="body2" title={row.resources_link}>
                {row.resources_link}
              </Typography>
            ),
          },
          {
            field: "Actions",
            flex: 0.2,
            minWidth: 130,
            sortable: false,
            headerName: "Actions",
            renderCell: ({ row }) => (
              <Box display="flex" alignItems="center" gap="10px">
                <IconButton
                  size="small"
                  color="primary"
                  variant="outlined"
                  onClick={(e) => {
                    e.stopPropagation();
                    toggleEdit(e, "edit", row);
                  }}
                >
                  <EditIcon />
                </IconButton>
                <IconButton
                  size="small"
                  color="secondary"
                  onClick={(e) => {
                    e.stopPropagation();
                    toggleDelete(e, row);
                  }}
                >
                  <DeleteIcon />
                </IconButton>
              </Box>
            ),
          },
        ]}
        currentPage={currentPage}
        pageSize={pageSize}
        setCurrentPage={setCurrentPage}
        setPageSize={setPageSize}
      />
    </>
  );
};

export default TableResourcesDetails;
