import { useEffect, useState, useRef, useCallback } from "react";
import {
  Button,
  Grid,
  IconButton,
  MenuItem,
  Select,
  Typography,
} from "@mui/material";
import Card from "@mui/material/Card";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import PageHeader from "src/@core/components/page-header";
import Translations from "src/layouts/components/Translations";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import { DefaultPaginationSettings } from "src/constants/general.const";
import { toastError, toastSuccess } from "src/utils/utils";
import DialogConfirmation from "src/views/dialog/DialogConfirmation";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import DialogAdditionalFeatures from "src/views/dialog/IT-Solution-Features/DialogAdditionalFeatures";
import TableAdditionalFeatures from "src/views/tables/IT-Solution-Features/TableAdditionalFeatures";
import DialogResources from "src/views/dialog/IT-Solution-Resources/DialogResources";
import TableResources from "src/views/tables/IT-Solution-Resources/TableResources";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import DialogResourcesDetails from "src/views/dialog/IT-Solution-Resources/DialogResourcesDetails";
import TableResourcesDetails from "src/views/tables/IT-Solution-Resources/TableResourcesDetails";

const ITSolutionResourcesDetails = () => {
  const navigate = useNavigate();
  const searchTimeoutRef = useRef();
  const [loading, setLoading] = useState(false);
  const [resourcesData, setResourcesData] = useState([]);
  const [search, setSearch] = useState("");
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(
    DefaultPaginationSettings.ROWS_PER_PAGE
  );
  const [status, setStatus] = useState("");
  const { id } = useParams();
  const location = useLocation();
  // Testimonials
  const [resourcesDialogOpen, setResourcesDialogOpen] = useState(false);
  const [resourcesDialogMode, setResourcesDialogMode] = useState("add");
  const [resourcesToEdit, setResourcesToEdit] = useState(null);
  // Confirmation
  const [confirmationDialogLoading, setConfirmationDialogLoading] =
    useState(false);
  const [confirmationDialogOpen, setConfirmationDialogOpen] = useState(false);
  const [resourcesToDelete, setResourcesToDelete] = useState(null);

  const toggleResourcesFormDialog = (
    e,
    mode = "add",
    resourcesToEdit = null
  ) => {
    setResourcesDialogOpen((prev) => !prev);
    setResourcesDialogMode(mode);
    setResourcesToEdit(resourcesToEdit);
  };

  const toggleConfirmationDialog = (e, dataToDelete = null) => {
    setConfirmationDialogOpen((prev) => !prev);
    setResourcesToDelete(dataToDelete);
  };

  const fetchData = ({
    currentPage,
    pageSize = DefaultPaginationSettings.ROWS_PER_PAGE,
    search,
    status,
  }) => {
    setLoading(true);
    let params = {
      page: currentPage,
      limit: pageSize,
      search: search,
      status: status,
    };

    axiosInstance
      .get(ApiEndPoints.ITSolutionResourcesDetails.list(id), { params })
      .then((response) => {
        setResourcesData(response.data.data);
        setTotalCount(response.data.data.totalCount);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData({
      currentPage: currentPage,
      pageSize: pageSize,
      search: search,
      status: status,
    });
  }, [currentPage, pageSize, search, status]);

  const onConfirmDelete = useCallback(
    (e) => {
      e?.preventDefault();
      setConfirmationDialogLoading(true);

      axiosInstance
        .delete(
          ApiEndPoints.ITSolutionResourcesDetails.delete(resourcesToDelete.id)
        )
        .then((response) => response.data)
        .then((response) => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
            search: search,
          });
          toggleConfirmationDialog();
          toastSuccess(response.message);
        })
        .catch((error) => {
          toastError(error);
        })
        .finally(() => {
          setConfirmationDialogLoading(false);
        });
    },
    [currentPage, resourcesToDelete, pageSize, search]
  );
  const handleIconClick = () => {
    navigate(-1);
  };
  return (
    <>
      <Grid container spacing={4} className="match-height">
        <PageHeader
          title={
            <Typography variant="h5">
              <Translations text={`${location.state?.title}`} />
            </Typography>
          }
          action={
            <Button variant="contained" onClick={toggleResourcesFormDialog}>
              Add Resources Details
            </Button>
          }
          backNavigation={
            <IconButton
              sx={{
                height: "30px",
                width: "30px",
                borderRadius: "50px",
                border: "2px solid #602de1c2",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
              }}
              onClick={handleIconClick}
            >
              <ArrowBackIcon sx={{ color: "#602de1c2", fontSize: "18px" }} />
            </IconButton>
          }
        />
        <Grid item xs={12}>
          <Card>
            <Box sx={{ p: 5 }}>
              <TableResourcesDetails
                search={search}
                loading={loading}
                rows={resourcesData}
                totalCount={totalCount}
                setCurrentPage={setCurrentPage}
                currentPage={currentPage}
                setPageSize={setPageSize}
                pageSize={pageSize}
                toggleDelete={toggleConfirmationDialog}
                toggleEdit={toggleResourcesFormDialog}
              />
            </Box>
          </Card>
        </Grid>
      </Grid>
      <DialogResourcesDetails
        mode={resourcesDialogMode}
        open={resourcesDialogOpen}
        toggle={toggleResourcesFormDialog}
        dataToEdit={resourcesToEdit}
        onSuccess={() => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
        }}
      />
      <DialogConfirmation
        loading={confirmationDialogLoading}
        title="Delete Resource Detail"
        subtitle="Are you sure you want to delete this Resource Detail?"
        open={confirmationDialogOpen}
        toggle={toggleConfirmationDialog}
        onConfirm={onConfirmDelete}
      />
    </>
  );
};

export default ITSolutionResourcesDetails;
